#include <stdio.h>

int main(void) {
  int age;
  if (scanf("%d", &age) != 1) {
    printf("input-error\n");
  } else if (age < 0 || age > 150) {
    printf("out-of-range\n");
  } else {
    printf("age:%d\n", age);
  }
  return 0;
}

