#include <stdio.h>

int main(void) {
  int count;
  if (scanf("%d", &count) != 1) {
    printf("input-error\n");
  } else if (count < 0 || count > 1000) {
    printf("out-of-range\n");
  } else {
    printf("count:%d\n", count);
  }
  return 0;
}
